            enter_sink.borrow_mut()(Event::PointerMove {
                target,
                x: x as f32,
                y: y as f32,
                hovering: true,
                leaving: false,
            });
        });
        motion.connect_leave(move |_motion| {
            sink.borrow_mut()(Event::PointerMove {
                target,
